            />
          </div>
        </div>
      </div>
    </template>

    <template #after>
      <!-- Detail Loading -->
      <div v-if="detailLoading" class="q-pa-xl text-center">
        <q-spinner color="primary" size="32px" />
      </div>

      <!-- Detail -->
      <div v-else-if="selectedEmail" class="email-detail-panel">
        <!-- Header (fixed) -->
        <div class="email-detail-header">
          <div class="q-pa-md">
            <div class="row items-center q-pa-sm rounded-borders sender-bar">
              <q-avatar size="28px" :color="getAvatarColor(selectedEmail.sender)" text-color="white" class="q-mr-sm">
                {{ (selectedEmail.sender || '?').charAt(0) }}
              </q-avatar>
              <div>
                <div class="text-body2 text-weight-medium">{{ selectedEmail.sender }}</div>
                <div class="text-caption text-grey-6">&lt;{{ selectedEmail.email }}&gt;</div>
              </div>
              <q-space />
              <span class="text-caption text-grey-6">{{ formatRelativeDate(selectedEmail.date || selectedEmail.created_on) }}</span>
            </div>

            <div class="row items-center q-gutter-sm q-mt-sm">
              <q-badge v-if="selectedEmail.classification" :color="getClassificationColor(selectedEmail.classification)" text-color="white">{{ $t(selectedEmail.classification.toLowerCase()) }}</q-badge>
              <div class="text-subtitle1 text-weight-medium">{{ selectedEmail.subject }}</div>
            </div>
          </div>

          <q-separator />

          <q-tabs
            v-model="activeTab"
            dense
            no-caps
            align="left"
            class="text-grey-7"
            active-color="primary"
            indicator-color="primary"
            narrow-indicator
          >
            <q-tab name="preview" :label="$t('preview')" />
            <q-tab name="attachments" v-if="threadAttachments.length">
              <div class="row items-center no-wrap">
                <span>{{ $t('attachments') }}</span>
                <q-badge color="primary" rounded :label="threadAttachments.length" class="q-ml-sm" size="xs" />
              </div>
            </q-tab>
            <q-tab v-if="extractedDocIds.length" name="extracted">
              <div class="row items-center no-wrap">
                <q-icon name="fact_check" size="16px" class="q-mr-xs" />
                <span>{{ $t('extracted_results') }}</span>
              </div>
            </q-tab>
            <q-tab name="source" :label="$t('source')" />
            <q-tab name="reply">
              <div class="row items-center no-wrap">
                <q-icon name="reply" size="16px" class="q-mr-xs" />
                <span>{{ $t('reply') }}</span>
              </div>
            </q-tab>
          </q-tabs>
          <q-separator />
        </div>

        <!-- Scrollable content -->
        <div class="email-detail-content">
          <q-tab-panels v-model="activeTab" animated class="bg-transparent fit">
            <q-tab-panel name="preview">
              <!-- Thread view: show all emails in the thread (oldest first) -->
              <template v-if="threadEmails.length > 1">
                <div
                  v-for="(threadEmail, idx) in threadEmails"
                  :key="threadEmail.id"
                  class="email-thread-entry"
                  :class="{ 'q-mt-md': idx > 0 }"
                >
                  <div class="row items-center q-mb-xs">
                    <q-avatar size="22px" :color="threadEmail.orchestration_status === 'sent' ? 'primary' : getAvatarColor(threadEmail.sender)" text-color="white" class="q-mr-sm">
                      <q-icon v-if="threadEmail.orchestration_status === 'sent'" name="reply" size="14px" />
                      <template v-else>{{ (threadEmail.sender || '?').charAt(0) }}</template>
                    </q-avatar>
                    <span class="text-body2 text-weight-medium">{{ threadEmail.sender }}</span>
                    <q-badge v-if="threadEmail.orchestration_status === 'sent'" color="primary" outline size="xs" class="q-ml-xs">{{ $t('sent') }}</q-badge>
                    <q-space />
                    <span class="text-caption text-grey-6">{{ formatRelativeDate(threadEmail.date || threadEmail.created_on) }}</span>
                  </div>
                  <div class="text-body2" style="line-height: 1.6; white-space: pre-wrap">{{ threadEmail.body }}</div>
                  <q-separator v-if="idx < threadEmails.length - 1" class="q-mt-md" />
                </div>
              </template>
              <!-- Single email (no thread) -->
              <template v-else>
                <div v-if="selectedEmail.body" class="text-body2" style="line-height: 1.6; white-space: pre-wrap">{{ selectedEmail.body }}</div>
                <div v-else class="text-center text-grey-5 q-pa-xl">
                  <q-icon name="description" size="48px" style="opacity: 0.4" />
                  <div class="q-mt-sm">{{ $t('no_email_body') }}</div>
                </div>
              </template>
            </q-tab-panel>

            <q-tab-panel name="attachments">
              <q-list separator>
                <q-item v-for="(att, i) in threadAttachments" :key="i">
                  <q-item-section avatar>
                    <q-icon :name="getAttachmentIcon(att.content_type)" color="grey-7" />
                  </q-item-section>
                  <q-item-section>
                    <q-item-label>{{ att.filename }}</q-item-label>
                    <q-item-label caption>{{ att.content_type }} · {{ formatFileSize(att.size) }}</q-item-label>
                  </q-item-section>
                  <q-item-section v-if="att.content" side>
                    <q-btn flat dense round icon="download" color="primary" size="sm" @click="downloadAttachment(att)" />
                  </q-item-section>
                </q-item>
              </q-list>
            </q-tab-panel>

            <q-tab-panel v-if="extractedDocIds.length" name="extracted">
              <ExtractedResultsTab :document-ids="extractedDocIds" />
            </q-tab-panel>

            <q-tab-panel name="source">
              <div class="text-subtitle2 q-mb-sm row items-center">
                <q-icon name="info" color="primary" size="20px" class="q-mr-sm" />
                {{ $t('email_metadata') }}
              </div>
              <q-list dense>
                <q-item v-for="f in metadataFields" :key="f.key" class="q-px-none">
                  <q-item-section side class="text-grey-6" style="min-width: 90px">{{ $t(f.key) }}</q-item-section>
                  <q-item-section class="text-caption" style="word-break: break-all">{{ f.value }}</q-item-section>
                </q-item>
              </q-list>

              <q-separator class="q-my-md" />

              <div class="row items-center justify-between q-mb-sm">
                <div class="text-subtitle2 row items-center">
                  <q-icon name="code" color="grey-7" size="20px" class="q-mr-sm" />
                  {{ $t('email_original_body') }}
                </div>
                <q-btn flat dense color="primary" icon="content_copy" :label="$t('copy')" size="sm" no-caps @click="copyBody" />
              </div>
              <template v-if="threadEmails.length > 1">
                <div v-for="(te, idx) in threadEmails" :key="te.id">
                  <div class="text-caption text-weight-medium text-grey-7 q-mb-xs" v-if="idx > 0">— {{ te.sender }} · {{ formatRelativeDate(te.date || te.created_on) }} —</div>
                  <pre class="source-body text-caption q-pa-sm rounded-borders" :class="{ 'q-mb-md': idx < threadEmails.length - 1 }">{{ te.body }}</pre>
                </div>
              </template>
              <pre v-else class="source-body text-caption q-pa-sm rounded-borders">{{ selectedEmail.body }}</pre>
            </q-tab-panel>

            <!-- Reply tab -->
            <q-tab-panel name="reply">
              <div class="text-caption text-grey-6 q-mb-sm">
                {{ $t('reply_to') }} {{ selectedEmail.sender }} &lt;{{ selectedEmail.email }}&gt;
              </div>
              <q-input
                v-model="replyText"
                type="textarea"
                outlined
                dense
                autogrow
                :placeholder="$t('type_reply')"
                class="q-mb-md"
                :input-style="{ minHeight: '120px' }"
              />
              <div class="row justify-end q-gutter-sm">
                <q-btn
                  unelevated
                  no-caps
                  color="primary"
                  icon="send"
                  :label="$t('send')"
                  :loading="sendingReply"
                  :disable="!replyText.trim()"
                  @click="sendReply"
                />
