            <template v-if="linkedMission">
              <span class="text-subtitle2 ellipsis q-mr-sm">{{ linkedMission.name }}</span>
              <q-space />
              <q-btn outline dense no-caps color="primary" icon="arrow_forward" :label="$t('mission')"
                @click="$router.push('/doc-net/missions/' + selectedEmail.mission_id)" />
            </template>
            <q-spinner v-else-if="detailLoading && selectedEmail?.mission_id" color="primary" size="16px" />
            <span v-else class="text-caption text-grey-6">{{ $t('no_linked_mission') }}</span>
          </div>
