      </div>
    </template>
  </q-splitter>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import { debounce } from 'quasar';
import logger from 'src/utils/logger';
import { useDocNetEmailStore } from 'src/store/DocNet/docnet-email.store';
import { useDocNetMissionStore } from 'src/store/DocNet/docnet-missions.store';
import { useDocNetWebSocketStore } from 'src/store/DocNet/docnet-websocket.store';
import DocNetEmailService from 'src/services/docnet/DocNetEmailService';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import type { DocNetEmail, DocNetEmailAttachment, DocNetMission } from 'src/@types/docnet';
import dateMixin from 'src/utils/date';
import {
  getClassificationColor,
  formatFileSize,
  getAttachmentIcon,
  getEmptyStateMessage,
  downloadAttachment,
  getFolderParams,
} from './email-utils';
import ExtractedResultsTab from './components/ExtractedResultsTab.vue';

export default defineComponent({
  name: 'DocNetEmail',
  mixins: [dateMixin],
  components: { ExtractedResultsTab },

  setup() {
    return {
      emailStore: useDocNetEmailStore(),
      missionStore: useDocNetMissionStore(),
    };
  },

  data() {
    const emailStore = useDocNetEmailStore();
    return {
      splitterModel: 25,
      // Mirrors emailStore.searchFilter so the input stays responsive; the
      // actual store write happens via the debounced handler below.
      search: emailStore.searchFilter,
      debouncedPushSearch: null as null | ((v: string) => void),
      activeTab: 'preview' as string,
      activeFolder: 'all' as string,
      detailLoading: false,
      linkedMission: null as DocNetMission | null,
      folderPages: { all: 1, unread: 1, read: 1 } as Record<string, number>,
      replyText: '',
      sendingReply: false,
      // Mission-linked documents for the "Extracted results" tab.
      // Fetched from ``/emails/{id}/extraction-results`` when the
      // selected email belongs to a mission; that endpoint now reads
      // from ``mission_documents`` (single source of truth since the
      // DOCB-9880 consolidation), so the tab shows whatever docs
      // reached the mission regardless of how they got there.
      extractedDocIds: [] as string[],
    };
  },

  computed: {
    emails(): DocNetEmail[] {
      return this.emailStore.emails;
    },
    loading(): boolean {
      return this.emailStore.loading;
    },
    unreadCount(): number {
      return this.emailStore.unreadCount;
    },
    selectedEmail(): DocNetEmail | null {
      return this.emailStore.selectedEmail;
    },
    page(): number {
      return this.emailStore.page;
    },
    totalPages(): number {
      return this.emailStore.totalPages;
    },
    filteredEmails(): DocNetEmail[] {
      // Folder filter is already applied server-side via getFolderParams(),
      // and search is applied server-side via emailStore.setSearchFilter().
      // The remaining client-side work is thread-grouping and sort, which
      // can't move to the backend without reshaping the payload.
      const filtered = this.emails as DocNetEmail[];

      // Group by mission_id — show only the latest email per thread
      const threadMap = new Map<string, DocNetEmail[]>();
      const noThread: DocNetEmail[] = [];
      for (const email of filtered) {
        const mid = email.mission_id;
        if (mid) {
          if (!threadMap.has(mid)) threadMap.set(mid, []);
          threadMap.get(mid)!.push(email);
        } else {
          noThread.push(email);
        }
      }

      const result: DocNetEmail[] = [];
      for (const [, thread] of threadMap) {
        // Sort by date desc, take the latest as the representative
        thread.sort((a, b) => new Date(b.created_on || b.date).getTime() - new Date(a.created_on || a.date).getTime());
        const latest = thread[0];
        latest._threadCount = thread.length;
        latest._threadEmails = thread;
        result.push(latest);
      }
      for (const email of noThread) {
        email._threadCount = 1;
        email._threadEmails = [email];
        result.push(email);
      }

      // Sort all by date desc
      result.sort((a, b) => new Date(b.created_on || b.date).getTime() - new Date(a.created_on || a.date).getTime());
      return result;
    },
    threadEmails(): DocNetEmail[] {
      if (!this.selectedEmail) return [];
      const thread = this.selectedEmail._threadEmails;
      if (!thread || thread.length <= 1) return [];
      return [...thread].sort((a, b) =>
        new Date(a.created_on || a.date).getTime() - new Date(b.created_on || b.date).getTime()
      );
    },

    /**
     * Attachments from every email in the current thread, deduped.
     *
     * Inbox grouping picks the *latest* email as the thread's
     * representative (line 427), which means after a reply is sent the
     * outbound message becomes ``selectedEmail``.  Outbound replies
     * never carry attachments, so gating the tab on
     * ``selectedEmail.attachments`` would hide it the moment a reply
     * exists — even though the inbound document is still part of the
     * conversation.  Mirroring how the Documents tab works
     * (mission-scoped, not per-email) keeps the user's mental model:
     * "this thread has a PDF" rather than "this specific message has
     * a PDF".
     *
     * Dedup key is ``filename:size`` because thread members can carry
     * the same attachment when forwarded — surfacing the duplicate
     * twice would be confusing without adding any information.
     */
    threadAttachments(): DocNetEmailAttachment[] {
      const list: DocNetEmailAttachment[] = [];
      const seen = new Set<string>();
      const emails = this.threadEmails.length > 0
        ? this.threadEmails
        : this.selectedEmail
          ? [this.selectedEmail]
          : [];
      for (const e of emails) {
        for (const att of e.attachments || []) {
          const key = `${att.filename}:${att.size}`;
          if (seen.has(key)) continue;
          seen.add(key);
          list.push(att);
        }
      }
      return list;
    },

    metadataFields(): { key: string; value: string }[] {
      // For threads, show metadata from the original (oldest) email
      const e = this.threadEmails.length > 0 ? this.threadEmails[0] : this.selectedEmail;
      if (!e) return [];
      return [
        { key: 'from', value: `${e.sender} <${e.email}>` },
        { key: 'to', value: e.to },
        { key: 'cc', value: e.cc },
        { key: 'email_reply_to', value: e.reply_to },
        { key: 'subject', value: e.subject },
        { key: 'date', value: this.formatDateAccordingToPreference(e.date || e.created_on) },
        { key: 'email_message_id', value: e.message_id },
        { key: 'email_in_reply_to', value: e.in_reply_to },
        { key: 'email_references', value: e.references },
        { key: 'classification', value: e.classification ? this.$t(e.classification.toLowerCase()) : '' },
        { key: 'status', value: e.orchestration_status ? this.$t(e.orchestration_status.toLowerCase()) : '' },
        { key: 'email_mission', value: this.linkedMission?.name || '' },
      ].filter((f): f is { key: string; value: string } => !!f.value);
    },
  },

  async mounted() {
    // 300ms matches the dashboard/missions-list debounce cadence — long
    // enough to coalesce a normal typing burst, short enough to feel live.
    this.debouncedPushSearch = debounce((value: string) => {
      this.emailStore.setSearchFilter(value || '', getFolderParams(this.activeFolder));
    }, 300);

    await this.emailStore.fetchEmails();
    await this.applyDeepLinkFromRoute();

    // Subscribe to emails channel for classification updates
    const orgId = getOrgId();
    if (orgId) {
      useDocNetWebSocketStore().subscribe(`emails:${orgId}`);
    }
  },

  watch: {
    // Re-apply the deep-link when the query param changes without a
    // full remount.  Happens when the user is already on
    // ``/doc-net/email`` (e.g. navigated here before, component is
    // kept alive) and clicks the Mission-detail "Open" button, or
    // when the URL is edited in place.  Without this watcher the new
    // ``?id=`` would be ignored and the user stays on the previously
    // selected email.
    '$route.query.id'(newId: unknown, oldId: unknown) {
      if (newId === oldId) return;
      void this.applyDeepLinkFromRoute();
    },
  },

  beforeUnmount() {
    this.markPreviousAsRead();
    const orgId = getOrgId();
    if (orgId) {
      useDocNetWebSocketStore().unsubscribe(`emails:${orgId}`);
    }
    // Clear the persisted search via the setter so page resets to 1 too —
    // direct mutation would leave a stale page cursor for re-entry.
    if (this.emailStore.searchFilter) {
      void this.emailStore.setSearchFilter('', getFolderParams(this.activeFolder));
    }
  },

  methods: {
    getAvatarColor(name: string): string {
      const colors = [
        'teal', 'indigo', 'orange', 'pink', 'cyan', 'deep-purple', 'blue-grey', 'brown',
        'red', 'green', 'purple', 'amber', 'light-blue', 'deep-orange', 'lime', 'blue',
      ];
      let hash = 0;
      for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
      }
      return colors[Math.abs(hash) % colors.length];
    },

    getClassificationColor,
    formatFileSize,
    getAttachmentIcon,
    getEmptyStateMessage,
    downloadAttachment,

    markPreviousAsRead() {
      const prev = this.emailStore.selectedEmail;
      if (prev && !prev.read) {
        this.emailStore.markAsRead(prev.id);
      }
    },

    /** Select the email referenced by ``?id=`` in the URL.  Called
     * from ``mounted()`` and from the ``$route.query.id`` watcher so
     * it works on fresh navigation and on same-component re-navigation
     * (keep-alive / same-route update).  Falls back to the newest
     * email when no id is set or the id can't be resolved — never
     * leaves the page with no selection. */
    async applyDeepLinkFromRoute(): Promise<void> {
      const queryId = this.$route.query.id;
      const requestedId = Array.isArray(queryId) ? queryId[0] : queryId;

      // Nothing to deep-link to.  If we already have a selection (e.g.
      // user came back to this page in a keep-alive), preserve it;
      // otherwise fall back to the newest email.
      if (!requestedId) {
        if (this.emailStore.selectedEmail) return;
        if (this.emails.length > 0) await this.selectEmail(this.emails[0]);
        return;
      }

      // Already in the list → select directly, no extra round-trip.
      const inList = this.emails.find((e: DocNetEmail) => e.id === requestedId);
      if (inList) {
        await this.selectEmail(inList);
        return;
      }

      // Not in the visible page → fetch by id and inject it into the
      // left-pane list BEFORE selecting.  Order matters: ``selectEmail``
      // sets ``selectedEmailId`` and the ``selectedEmail`` getter resolves
      // it by searching ``state.emails`` — if we selected first, the
      // getter would briefly return null and the right pane would render
      // the empty-state until the unshift landed.
      let fetched: DocNetEmail | undefined;
      try {
        fetched = await this.emailStore.fetchEmailDetail(String(requestedId));
      } catch (err) {
        // eslint-disable-next-line no-console
        console.warn(
          `[DocNetEmail] deep-link id=${requestedId} could not be fetched:`,
          err,
        );
      }

      if (fetched) {
        if (!this.emails.some((e: DocNetEmail) => e.id === fetched!.id)) {
          this.emailStore.emails.unshift(fetched);
        }
        await this.selectEmail(fetched);
        return;
      }

      // Fetch failed → fall back to newest so the page isn't stuck on a
      // blank right pane.
      if (this.emails.length > 0) await this.selectEmail(this.emails[0]);
    },

    async selectEmail(email: DocNetEmail) {
      // Mark the previously viewed email as read before switching
      this.markPreviousAsRead();

      const targetId = email.id;
      this.emailStore.selectedEmailId = targetId;
      this.activeTab = 'preview';
      this.linkedMission = null;
      this.extractedDocIds = [];
      this.replyText = '';
      this.detailLoading = true;
      try {
        await this.emailStore.fetchEmailDetail(targetId);
        if (this.emailStore.selectedEmailId !== targetId) return;
        if (email.mission_id) {
          try {
            await this.missionStore.fetchMission(email.mission_id, true);
            if (this.emailStore.selectedEmailId !== targetId) return;
            this.linkedMission = this.missionStore.currentMission;
          } catch {
            this.linkedMission = null;
          }
          // Fetch mission-scoped documents so the Extracted-results
          // tab gate + content don't need ``document_ids`` on the
          // email (which was removed in the DOCB-9880
          // consolidation).  Best-effort — a failure leaves the tab
          // hidden, which is cleaner than showing an empty one.
          try {
            const svc = new DocNetEmailService();
            const res = await svc.fetchExtractionResults(targetId);
            if (this.emailStore.selectedEmailId !== targetId) return;
            this.extractedDocIds = (res.documents || [])
              .map((d: { document_id?: string }) => d.document_id || '')
              .filter((id: string) => !!id);
          } catch {
            this.extractedDocIds = [];
          }
        }
      } finally {
        if (this.emailStore.selectedEmailId === targetId) {
          this.detailLoading = false;
        }
      }
    },

    async goToPage(page: number) {
      this.folderPages[this.activeFolder] = page;
      await this.emailStore.goToPage(page, getFolderParams(this.activeFolder));
    },

    async changeFolder(folder: string) {
      const savedPage = this.folderPages[folder] || 1;
      await this.emailStore.goToPage(savedPage, getFolderParams(folder));
    },

    onSearchInput(value: string | number | null) {
      // Keep the input model live; push to the store via the debounce so
      // we don't hit the API on every keystroke.
      const text = value == null ? '' : String(value);
      this.search = text;
      this.debouncedPushSearch?.(text);
    },

    formatRelativeDate(date: string): string {
      if (!date) return '';
      const diffMs = Date.now() - new Date(date).getTime();
      const mins = Math.floor(diffMs / 60000);
      const hours = Math.floor(diffMs / 3600000);
      const days = Math.floor(diffMs / 86400000);
      if (mins < 1) return 'Just now';
      if (mins < 60) return `${mins}m ago`;
      if (hours < 24) return `${hours}h ago`;
      if (days === 1) return 'Yesterday';
      if (days < 7) return `${days}d ago`;
      return new Date(date).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
    },

    copyBody() {
      if (!this.selectedEmail?.body) return;
      navigator.clipboard.writeText(this.selectedEmail.body);
      notify.success(this.$t('copied_to_clipboard'));
    },

    async sendReply() {
      if (!this.selectedEmail || !this.replyText.trim()) return;
      this.sendingReply = true;
      try {
        const email = this.selectedEmail;
        // For threaded replies, always reply to the original inbound email,
        // not a sent reply (which would have our own address as sender).
        const inbound = this.threadEmails.find(e => e.orchestration_status !== 'sent') || email;
        const configId = inbound.email_import_config_id
          ?? this.threadEmails.find(e => e.email_import_config_id)?.email_import_config_id;
        const missionId = inbound.mission_id
          ?? this.threadEmails.find(e => e.mission_id)?.mission_id;
        const { getAuthorizationToken, IMPORT_EMAIL_URL } = await import('src/pages/APIs');
        const orgId = getOrgId();

        const token = await getAuthorizationToken();
        const emailServiceUrl = IMPORT_EMAIL_URL;

        const resp = await fetch(`${emailServiceUrl}/email_import/send_reply`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': token,
            'X-Org-ID': orgId,
          },
          body: JSON.stringify({
            to: inbound.email,
            subject: `Re: ${inbound.subject.replace(/^Re:\s*/i, '')}`,
            body_html: `<p>${this.replyText.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/\n/g, '<br/>')}</p>`,
            body_text: this.replyText,
            in_reply_to: inbound.message_id || '',
            references: inbound.message_id || '',
            email_import_config_id: configId,
          }),
        });

        if (!resp.ok) {
          const err = await resp.text();
          throw new Error(err);
        }

        const respData = await resp.json();

        // Store outbound email in docnet for thread view
        try {
          const { api } = await import('src/pages/APIs');
          await fetch(`${api.docnet_emails}`, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': token,
              'X-Org-ID': orgId,
            },
            body: JSON.stringify({
              sender: respData.mail_from || 'DocBits',
              email: respData.mail_from || '',
              subject: inbound.subject.replace(/^Re:\s*/i, ''),
              body: this.replyText,
              date: new Date().toISOString(),
              message_id: respData.outbound_message_id || '',
              in_reply_to: inbound.message_id || '',
              references: inbound.message_id || '',
              to: inbound.email,
              orchestration_status: 'sent',
              ...(missionId ? { mission_id: missionId } : {}),
              ...(configId ? { email_import_config_id: configId } : {}),
            }),
          });
        } catch {
          // Non-critical — reply was sent, storage is best-effort
        }

        // Refresh email list to show the sent reply
        await this.emailStore.fetchEmails(true);

        notify.success(this.$t('reply_sent'));
        this.replyText = '';
        this.activeTab = 'preview';
      } catch (err) {
        logger.error('[DocNet] Reply failed:', err);
        notify.error(this.$t('reply_failed'));
      } finally {
        this.sendingReply = false;
      }
    },
  },
});
</script>

