<template>
  <div class="extracted-results-tab q-pa-md">
    <!-- Loading -->
    <div v-if="loading" class="text-center q-pa-xl">
      <q-spinner color="primary" size="32px" />
      <div class="text-caption text-grey-6 q-mt-sm">{{ $t('loading_extraction_results') }}</div>
    </div>

    <!-- No results -->
    <div v-else-if="!documents.length" class="text-center text-grey-5 q-pa-xl">
      <q-icon name="search_off" size="48px" style="opacity: 0.4" />
      <div class="q-mt-sm">{{ $t('no_extraction_results') }}</div>
    </div>

    <!-- Document results -->
    <div v-else>
      <div
        v-for="doc in documents"
        :key="doc.document_id"
        class="doc-result q-mb-lg"
      >
        <!-- Document header -->
        <div class="row items-center q-mb-sm">
          <q-icon name="description" color="primary" size="22px" class="q-mr-sm" />
          <span class="text-subtitle2 text-weight-bold">
            {{ docTitle(doc) }}
          </span>
          <q-badge
            v-if="docType(doc)"
            color="primary"
            outline
            class="q-ml-sm"
          >
            {{ docType(doc) }}
          </q-badge>
          <q-badge
            v-if="docStatus(doc)"
            :class="statusClass(docStatus(doc))"
            class="q-ml-xs"
          >
            {{ $t(docStatus(doc)) }}
          </q-badge>
          <q-space />
          <span class="inline-block">
            <q-btn
              outline
              dense
              no-caps
              color="primary"
              :icon="isDocProcessing(doc) ? 'block' : 'arrow_forward'"
              :label="$t('open_document')"
              size="sm"
              :disable="isDocProcessing(doc)"
              @click="openDocument(doc.document_id)"
            />
            <q-tooltip v-if="isDocProcessing(doc)">
              {{ $t('document_still_processing') || 'Document is still being processed' }}
            </q-tooltip>
          </span>
        </div>

        <!-- Extraction fields -->
        <q-card flat bordered>
          <q-list separator dense>
            <q-item v-for="field in extractedFields(doc)" :key="field.name">
              <q-item-section>
                <q-item-label caption class="text-grey-6">{{ formatFieldName(field.name) }}</q-item-label>
                <q-item-label class="text-weight-medium">{{ field.value ?? '—' }}</q-item-label>
              </q-item-section>
              <q-item-section v-if="field.confidence != null" side>
                <q-badge
                  :color="confidenceColor(field.confidence)"
                  outline
                  class="q-px-sm"
                >
                  {{ Math.round(field.confidence * 100) }}%
                </q-badge>
              </q-item-section>
            </q-item>
          </q-list>

          <!-- No fields extracted yet -->
          <div v-if="!extractedFields(doc).length" class="text-center text-grey-5 q-pa-md">
            {{ $t('extraction_pending') }}
          </div>
        </q-card>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { api, getAuthorizationToken } from 'src/pages/APIs';
import { getOrgId } from 'src/utils/organization/org_id_helper';

export default defineComponent({
  name: 'ExtractedResultsTab',

  props: {
    documentIds: {
      type: Array as PropType<string[]>,
      default: () => [],
    },
  },

  data() {
    return {
      loading: false,
      documents: [] as any[],
    };
  },

  watch: {
    documentIds: {
      immediate: true,
      handler(ids: string[]) {
        if (ids?.length) this.fetchResultsDirect(ids);
        else this.documents = [];
      },
    },
  },

  methods: {
    async fetchResultsDirect(docIds: string[]): Promise<void> {
      this.loading = true;
      try {
        const token = await getAuthorizationToken();
        const orgId = getOrgId();
        const headers = { Authorization: `Bearer ${token}` };

        const results = await Promise.all(
          docIds.map(async (docId) => {
            try {
              // Fetch document details and extraction results in parallel
              const [detailsResp, extractionResp] = await Promise.all([
                fetch(
                  `${api.get_document_by_id}/by-id/${docId}?org_id=${orgId}`,
                  { headers },
                ),
                fetch(
                  `${api.get_extracted_document_by_id}`,
                  {
                    method: 'POST',
                    headers: { ...headers, 'Content-Type': 'application/x-www-form-urlencoded' },
                    body: new URLSearchParams({ doc_id: docId, org_id: orgId || '' }),
                  },
                ),
              ]);

              const details = detailsResp.ok ? await detailsResp.json() : {};
              const extraction = extractionResp.ok ? await extractionResp.json() : {};

              return {
                document_id: docId,
                details,
                extraction,
              };
            } catch {
              return null;
            }
          }),
        );

        this.documents = results.filter(Boolean);
      } catch {
        this.documents = [];
      } finally {
        this.loading = false;
      }
    },

    docTitle(doc: any): string {
      const details = doc.details;
      if (!details) return doc.document_id.slice(0, 8);
      return details.filename || details.title || details.file_name || doc.document_id.slice(0, 8);
    },

    docType(doc: any): string {
      return doc.details?.doc_type || doc.details?.document_type || '';
    },

    docStatus(doc: any): string {
      return doc.details?.status || '';
    },

    isDocProcessing(doc: any): boolean {
      const status = this.docStatus(doc);
      return !status || ['new', 'running', 'restarted'].includes(status);
    },

    statusClass(status: string): string {
      const map: Record<string, string> = {
        new: 'bg-light-green-6',
        ready_for_review: 'bg-amber-7',
        ready_for_validation: 'bg-amber-7',
        validating: 'bg-amber-7',
        validated_pending_export: 'bg-amber-7',
        pending_confirmation: 'bg-amber-7',
        finished: 'bg-light-green-6',
        workflow: 'bg-light-green-6',
        completed: 'bg-light-green-6',
        restarted: 'bg-blue-14',
        error: 'bg-red-13',
        export_error: 'bg-red-13',
      };
      return map[status?.toLowerCase()] || 'bg-grey';
    },

    extractedFields(doc: any): { name: string; value: any; confidence?: number }[] {
      const extraction = doc.extraction;
      if (!extraction) return [];

      // doc2-api format: { fields: [ { name, value, confidence, formatted_value, ... } ] }
      if (Array.isArray(extraction.fields)) {
        return extraction.fields
          .filter((f: any) => f.value != null && f.value !== '')
          .map((f: any) => ({
            name: f.name,
            value: f.formatted_value || f.value,
            confidence: f.confidence != null ? f.confidence / 100 : undefined,
          }));
      }

      return [];
    },

    formatFieldName(name: string): string {
      return name
        .replace(/_/g, ' ')
        .replace(/\b\w/g, (c) => c.toUpperCase());
    },

    confidenceColor(confidence: number): string {
      if (confidence >= 0.9) return 'positive';
      if (confidence >= 0.7) return 'warning';
      return 'negative';
    },

    openDocument(docId: string): void {
      this.$router.push(`/field_validation_v1/${docId}`);
    },
  },
});
</script>

<style lang="scss" scoped>
.doc-result {
  &:last-child {
    margin-bottom: 0;
  }
}
</style>
