import type { DocNetEmail, DocNetEmailAttachment } from 'src/@types/docnet';

export function filterEmails(emails: DocNetEmail[], search: string): DocNetEmail[] {
  if (!search) return emails;
  const term = search.toLowerCase();
  return emails.filter(
    (e) => e.subject.toLowerCase().includes(term) || e.sender.toLowerCase().includes(term),
  );
}

