  credit_note: { label: 'credit_note', color: 'indigo' },
  order: { label: 'order', color: 'purple' },
  order_confirmation: { label: 'order_confirmation', color: 'deep-purple' },
  quote: { label: 'quote', color: 'teal' },
  delivery_note: { label: 'delivery_note', color: 'cyan' },
  complaint: { label: 'complaint', color: 'red' },
  inquiry: { label: 'inquiry', color: 'orange' },
  reminder: { label: 'reminder', color: 'amber' },
  contract: { label: 'contract', color: 'brown' },
