export const ORCHESTRATION_STATUSES: Record<string, { label: string; color: string }> = {
  in_progress: { label: 'in_progress', color: 'blue' },
  done: { label: 'done', color: 'positive' },
  needs_approval: { label: 'needs_approval', color: 'orange' },
  ingested: { label: 'ingested', color: 'grey' },
};

export function getOrchestrationStatusColor(status?: string): string {
  if (!status) return 'grey';
  return ORCHESTRATION_STATUSES[status.toLowerCase()]?.color || 'grey';
}

export function getOrchestrationStatusLabel(status?: string): string {
  if (!status) return 'Unknown';
  return ORCHESTRATION_STATUSES[status.toLowerCase()]?.label || status;
}

export function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

export function getAttachmentIcon(contentType: string): string {
  if (contentType.includes('pdf')) return 'picture_as_pdf';
  if (contentType.includes('image')) return 'image';
  if (contentType.includes('spreadsheet') || contentType.includes('excel')) return 'table_chart';
  if (contentType.includes('word') || contentType.includes('document')) return 'description';
  return 'attach_file';
}

export function getClassificationColor(type: string): string {
  if (!type) return 'grey';
  return EMAIL_CLASSIFICATIONS[type.toLowerCase()]?.color || 'grey';
}

export function getFolderParams(folder: string): { read?: boolean } | undefined {
  return folder === 'all' ? undefined : { read: folder === 'read' };
}

export function getEmptyStateMessage(folder: string): string {
  if (folder === 'unread') return 'No unread emails';
  if (folder === 'read') return 'No read emails';
  return 'No emails found';
}

export function downloadAttachment(att: DocNetEmailAttachment): void {
  if (!att.content) return;
  const byteChars = atob(att.content);
  const byteNumbers = new Array(byteChars.length);
  for (let i = 0; i < byteChars.length; i++) {
    byteNumbers[i] = byteChars.charCodeAt(i);
  }
  const blob = new Blob([new Uint8Array(byteNumbers)], { type: att.content_type });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = att.filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}
